def shortestWithBreaks(grid, k):
    rows, cols = len(grid), len(grid[0])
    if rows == 1 and cols == 1:
        return 0
    k = min(k, rows + cols - 3)
    best = [[-1] * cols for _ in range(rows)]
    best[0][0] = k
    frontier = [(0, 0, k)]
    steps = 0
    while frontier:
        steps += 1
        nxt = []
        for r, c, rem in frontier:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    nrem = rem - grid[nr][nc]
                    if nrem > best[nr][nc]:
                        if nr == rows - 1 and nc == cols - 1:
                            return steps
                        best[nr][nc] = nrem
                        nxt.append((nr, nc, nrem))
        frontier = nxt
    return -1
